effect.shader:
/** Um ponto da camada, pré-multiplicado; fora dela, transparente. */
vec4 ponto(ivec2 p, ivec2 T) {
    if (p.x < 0 || p.y < 0 || p.x >= T.x || p.y >= T.y) return vec4(0.0);
    vec4 c = texelFetch(inputImg, p, 0);
    return vec4(c.rgb * c.a, c.a);
}

void main() {
    ivec2 T = textureSize(inputImg, 0);
    vec2 tam = vec2(T);
    vec2 pos = floor(min(acScreenNorm * tam, tam - 1.0)) + 0.5;
    vec2 centro = viewCenter * tam;
    vec2 d = pos - centro;

    vec2 lido = pos;
    bool existe = true;
    float a = radians(clamp(fov, 0.0, 179.99));
    if (a > 0.0) {
        float meia = fovOrientation == 0 ? 0.5 * tam.x : (fovOrientation == 1 ? 0.5 * tam.y : 0.5 * length(tam));
        float f = meia / tan(0.5 * a);
        float u2 = dot(d, d) / (f * f);
        if (reverse) lido = centro + d / sqrt(1.0 + u2);
        else if (u2 < 1.0) lido = centro + d / sqrt(1.0 - u2);
        else existe = false;
    }
    if (!existe) { fragColor = vec4(0.0); return; }

    // Bilinear na cor pré-multiplicada (medido: é como o AE lê).
    vec2 q = lido - 0.5;
    ivec2 b = ivec2(floor(q));
    vec2 t = q - vec2(b);
    vec4 c = mix(mix(ponto(b, T), ponto(b + ivec2(1, 0), T), t.x), mix(ponto(b + ivec2(0, 1), T), ponto(b + ivec2(1, 1), T), t.x), t.y);
    fragColor = c.a > 0.0 ? vec4(min(c.rgb / c.a, vec3(1.0)), c.a) : vec4(0.0);
}
